# Add pathway columns to jv_deals
print("=== ADDING PATHWAY COLUMNS TO jv_deals ===")

migration_sql = """
-- Tokenized pathway columns
ALTER TABLE jv_deals ADD COLUMN IF NOT EXISTS tokenized_enabled boolean DEFAULT false;
