ALTER TABLE jv_deals ADD COLUMN IF NOT EXISTS tokenized_launch_date text;
ALTER TABLE jv_deals ADD COLUMN IF NOT EXISTS tokenized_close_date text;

-- JV pathway columns
ALTER TABLE jv_deals ADD COLUMN IF NOT EXISTS jv_enabled boolean DEFAULT false;
ALTER TABLE jv_deals ADD COLUMN IF NOT EXISTS jv_status text DEFAULT 'JV_NOT_AVAILABLE';
ALTER TABLE jv_deals ADD COLUMN IF NOT EXISTS jv_minimum_contribution numeric DEFAULT 20000;
