ALTER TABLE jv_deals ADD COLUMN IF NOT EXISTS jv_close_date text;

-- Buyer pathway columns
ALTER TABLE jv_deals ADD COLUMN IF NOT EXISTS buyer_enabled boolean DEFAULT false;
ALTER TABLE jv_deals ADD COLUMN IF NOT EXISTS buyer_status text DEFAULT 'BUYER_NOT_AVAILABLE';
ALTER TABLE jv_deals ADD COLUMN IF NOT EXISTS buyer_asking_price numeric DEFAULT 0;
