ALTER TABLE jv_deals ADD COLUMN IF NOT EXISTS earnest_money_required boolean DEFAULT false;
ALTER TABLE jv_deals ADD COLUMN IF NOT EXISTS proof_of_funds_required boolean DEFAULT true;
ALTER TABLE jv_deals ADD COLUMN IF NOT EXISTS financing_allowed boolean DEFAULT true;
