ALTER TABLE jv_deals ADD COLUMN IF NOT EXISTS closing_target_days integer DEFAULT 30;
ALTER TABLE jv_deals ADD COLUMN IF NOT EXISTS offer_expiration_days integer DEFAULT 7;

-- Publish workflow columns
ALTER TABLE jv_deals ADD COLUMN IF NOT EXISTS publish_state text DEFAULT 'draft';
ALTER TABLE jv_deals ADD COLUMN IF NOT EXISTS slug text;
ALTER TABLE jv_deals ADD COLUMN IF NOT EXISTS subtitle text;
ALTER TABLE jv_deals ADD COLUMN IF NOT EXISTS capital_raised numeric DEFAULT 0;
ALTER TABLE jv_deals ADD COLUMN IF NOT EXISTS progress_percentage integer DEFAULT 0;
ALTER TABLE jv_deals ADD COLUMN IF NOT EXISTS estimated_completion text;
ALTER TABLE jv_deals ADD COLUMN IF NOT EXISTS featured boolean DEFAULT false;

-- Add constraints for status enums
DO $$ BEGIN
  ALTER TABLE jv_deals ADD CONSTRAINT jv_deals_tokenized_status_check CHECK (
    tokenized_status IN ('TOKENIZED_NOT_AVAILABLE','TOKENIZED_COMING_SOON','TOKENIZED_WAITLIST','TOKENIZED_OPEN','TOKENIZED_PAUSED','TOKENIZED_FULLY_ALLOCATED','TOKENIZED_CLOSED')
  );
EXCEPTION WHEN duplicate_object THEN NULL; END $$;

DO $$ BEGIN
  ALTER TABLE jv_deals ADD CONSTRAINT jv_deals_jv_status_check CHECK (
    jv_status IN ('JV_NOT_AVAILABLE','JV_COMING_SOON','JV_OPEN','JV_PAUSED','JV_CLOSED')
  );
EXCEPTION WHEN duplicate_object THEN NULL; END $$;

DO $$ BEGIN
  ALTER TABLE jv_deals ADD CONSTRAINT jv_deals_buyer_status_check CHECK (
    buyer_status IN ('BUYER_NOT_AVAILABLE','BUYER_OPEN','BUYER_PAUSED','BUYER_CLOSED','BUYER_UNDER_CONTRACT')
  );
EXCEPTION WHEN duplicate_object THEN NULL; END $$;

DO $$ BEGIN
  ALTER TABLE jv_deals ADD CONSTRAINT jv_deals_publish_state_check CHECK (
    publish_state IN ('draft','under_review','approved','published','paused','closed','archived')
  );
EXCEPTION WHEN duplicate_object THEN NULL; END $$;

-- Set defaults for existing deals based on current data
UPDATE jv_deals SET 
  tokenized_enabled = false,
  tokenized_status = 'TOKENIZED_COMING_SOON',
  jv_enabled = true,
  jv_status = 'JV_OPEN',
  jv_minimum_contribution = CASE WHEN min_investment >= 20000 THEN min_investment ELSE 20000 END,
  buyer_enabled = true,
  buyer_status = 'BUYER_OPEN',
  buyer_asking_price = sale_price,
  slug = LOWER(REPLACE(title, ' ', '-')),
  publish_state = CASE WHEN published = true THEN 'published' ELSE 'draft' END,
  capital_raised = 0,
  progress_percentage = 0
WHERE publish_state IS NULL OR publish_state = 'draft';

-- Create deal_pathways audit table
CREATE TABLE IF NOT EXISTS deal_pathway_events (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  deal_id text NOT NULL REFERENCES jv_deals(id),
  admin_user_id text,
  pathway text NOT NULL,
  field_changed text NOT NULL,
  before_value text,
  after_value text,
  trace_id text,
  version integer,
  publish_state text,
  created_at timestamptz DEFAULT now()
);

-- Create index on deal_id
CREATE INDEX IF NOT EXISTS idx_deal_pathway_events_deal_id ON deal_pathway_events(deal_id);
CREATE INDEX IF NOT EXISTS idx_deal_pathway_events_created_at ON deal_pathway_events(created_at DESC);

-- Enable RLS
ALTER TABLE deal_pathway_events ENABLE ROW LEVEL SECURITY;
CREATE POLICY deal_pathway_events_owner_all ON deal_pathway_events FOR ALL USING (
  auth.uid() IN (SELECT id FROM auth.users WHERE raw_app_meta_data->>'role' IN ('owner','admin'))
);
CREATE POLICY deal_pathway_events_anon_select ON deal_pathway_events FOR SELECT TO anon USING (true);

-- Create sync report table
CREATE TABLE IF NOT EXISTS deal_sync_reports (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  deal_id text NOT NULL REFERENCES jv_deals(id),
  version integer,
  database_synced boolean DEFAULT false,
  api_synced boolean DEFAULT false,
  landing_synced boolean DEFAULT false,
  mobile_synced boolean DEFAULT false,
  cache_invalidated boolean DEFAULT false,
  sync_latency_ms integer,
  final_status text,
  trace_id text,
  created_at timestamptz DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_deal_sync_reports_deal_id ON deal_sync_reports(deal_id);
ALTER TABLE deal_sync_reports ENABLE ROW LEVEL SECURITY;
CREATE POLICY deal_sync_reports_owner_all ON deal_sync_reports FOR ALL USING (
  auth.uid() IN (SELECT id FROM auth.users WHERE raw_app_meta_data->>'role' IN ('owner','admin'))
);
CREATE POLICY deal_sync_reports_anon_select ON deal_sync_reports FOR SELECT TO anon USING (true);
"""

rows = execute_sql(migration_sql)
if rows is not None:
